// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _run(uint256 d1, uint256 d2) internal {
        d1 = bound(d1, 0, 1000000000000000000000000000000);
        d2 = bound(d2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d1 + d2);
        uint256 min;
        try c.MinDeposit() returns (uint256 __r) { min = __r; } catch { return; }
        vm.assume(d1 >= min && d2 >= min);
        try c.Deposit{value: d1}() {} catch { return; }
        try c.Deposit{value: d2}() {} catch { return; }
        uint256 recorded;
        try c.balances(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        uint larger = d1 >= d2 ? d1 : d2;
        assertTrue(recorded >= larger);
    }

    function testFuzz_run(uint256 d1, uint256 d2) public {
        _run(d1, d2);
    }

    receive() external payable {}
}
